import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E8%85%95%E6%99%82%E8%A8%88.html","title":"腕時計","lang":"en-US","frontmatter":{},"git":{"createdTime":1707021122000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":4}]},"readingTime":{"minutes":0.69,"words":207},"filePathRelative":"腕時計.md"}`),a={name:`腕時計.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="腕時計" tabindex="-1"><a class="header-anchor" href="#腕時計"><span>腕時計</span></a></h1><p><a href="./雑多なメモ.html">雑多なメモ</a></p><h2 id="カシオ-mw-240-4bjh-2026-05-10-日" tabindex="-1"><a class="header-anchor" href="#カシオ-mw-240-4bjh-2026-05-10-日"><span>カシオ MW-240-4BJH 2026-05-10 (日)</span></a></h2><p><a href="https://www.yodobashi.com/product-detail/100000001006250481/" target="_blank" rel="noopener noreferrer">ヨドバシ.com - カシオ CASIO スタンダードウォッチ MW-240-4BJH 通販【全品無料配達】</a></p><p>親の家から行く場合と自分の家から行く場合で腕時計が２つ欲しくなったので、もう一つ買う。</p><p>5気圧防水の普段使っている下の奴よりもスリムな奴にしてみる。まぁ安いものだし壊れてもいいか、という事で。 2280円だった。</p><h2 id="カシオmrw-200hj-1bjh-2024-02-04" tabindex="-1"><a class="header-anchor" href="#カシオmrw-200hj-1bjh-2024-02-04"><span>カシオMRW-200HJ-1BJH 2024-02-04</span></a></h2><p><a href="./サーフィン.html">サーフィン</a>してて、時間を知りたくなる事が多いため、防水の腕時計を買う。</p><ul><li><a href="https://www.casio.com/jp/watches/casio/product.MRW-200HJ-1B/" target="_blank" rel="noopener noreferrer">MRW-200HJ-1BJH - CASIO</a></li><li><a href="https://www.yodobashi.com/product/100000001006250463/" target="_blank" rel="noopener noreferrer">ヨドバシ.com - カシオ CASIO MRW-200HJ-1BJH [スタンダードウォッチ] 通販【全品無料配達】</a></li></ul><p>10気圧防水。2310円だった。2月1日の深夜にポチって2/4の午前中に届く。奄美大島にしてはなかなか早い。 1000円くらいの10気圧防水のものもあったのだが、ちょっと不安だったので1グレード上のもので。 まぁ壊れても惜しくないくらいの値段ではある。</p><p>回転ベゼルがついているので、これで潮の干潮とか満潮に合わせて行こうかな、と思っている。</p><p>第一印象としてはゴツくないけどちゃちすぎもしないで、自分的にはちょうど良い感じで好印象。あとはパドリングしてみてだな。</p><p>なお、説明書は「CASIO ANA(D3H-2)* JA」と書いてある。なんか複数の種類の説明書がまとまっているっぽい。</p><h3 id="少し使った感じ、なかなか良い-2024-02-09" tabindex="-1"><a class="header-anchor" href="#少し使った感じ、なかなか良い-2024-02-09"><span>少し使った感じ、なかなか良い 2024-02-09</span></a></h3><p>数日つかってみたが、海で腕時計があると便利だな。 たまにパドリングで腕に当たっていたくなることもあるが。 回転ベゼルも便利だし、防水機能も今の所問題なさそう。</p><p>このくらいでちょうど良かったな。</p>`,16)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};